    "question": "Le score de Ferriman et Gallwey modifié permet d'évaluer le degré d'hirsutisme chez une femme :",
    "propositions": {
      "A": "Il apprécie la sévérité de l'hirsutisme par la quantification du degré de la pousse des poils",
      "B": "Il est coté de 0 (absence de poils) à 4 (poils abondants)",
      "C": "Neuf parties du corps sont explorées et cotées de 1 à 4 en fonction de l'importance de la pilosité",
      "D": "Un score supérieur à 15 définit l'hirsutisme",
      "E": "Les poils définitifs se distinguent du duvet par leur longueur de plus de 0,5 cm et leur pigmentation"
    },
    "bonnes_reponses": [
      "A",
      "B",
      "C",
      "E"
    ],
