    "remarque": "Erreur du corrigé type : réponse corrigée par Claude, voir ton cours. Corrigé type = ABCD. A est vraie hors urgence : on confirme le diagnostic avant de traiter (en crise aiguë, on traite sans attendre, après prélèvement). B, C, D sont fausses ; E est vraie."
