      "A": "Le cancer papillaire est le plus fréquent des cancers différenciés de la thyroïde",
      "B": "Le cancer anaplasique est une tumeur d'excellent pronostic",
      "C": "Le carcinome médullaire de la thyroïde (CMT) se développe aux dépens des cellules parafolliculaires.",
      "D": "Le cancer vésiculaire représente la forme la plus fréquente chez l'enfant et l'adulte jeune exposés aux radiations ionisantes.",
      "E": "Les antécédents d'irradiation cervicale externe dans l'enfance constituent un facteur de risque majeur de carcinome papillaire."
