      "C": "Le phéochromocytome doit toujours être dépisté et opéré en premier avant toute chirurgie thyroïdienne.",
      "D": "L'hyperparathyroïdie primaire de la NEM 2A est le plus souvent liée à une hyperplasie des quatre glandes parathyroïdes.",
