    "question": "Concernant le carcinome anaplasique de la thyroïde :",
    "propositions": {
      "A": "C'est une tumeur maligne extrêmement agressive, touchant préférentiellement les sujets âgés.",
      "B": "Elle se manifeste cliniquement par une tuméfaction cervicale dure (pierreuse) augmentant très rapidement de volume, souvent douloureuse et compressive (dyspnée, dysphagie, dysphonie).",
      "C": "Histologiquement, elle est constituée de cellules indifférenciées polymorphes avec de nombreuses mitoses et des zones de nécrose.",
      "D": "Son pronostic est redoutable, avec une médiane de survie globale de l'ordre de quelques mois.",
      "E": "Elle est de découverte fortuite histologique après une chirurgie pour goitre multinodulaire bénin, et guérit systématiquement par une simple surveillance annuelle."
    },
