    "question": "Concernant la thyroïdite d'Hashimoto :",
    "propositions": {
      "A": "C'est une pathologie thyroïdienne d'origine auto-immune, représentant la cause la plus fréquente d'hypothyroïdie.",
      "B": "Elle touche préférentiellement les femmes et s'associe fréquemment à d'autres maladies auto-immunes.",
      "C": "La biologie met en évidence la présence d'anticorps anti-TPO et/ou anti-Tg à des taux souvent très élevés.",
      "D": "L'examen histologique retrouve typiquement un infiltrat lymphocytaire dense avec des centres germinatifs et des cellules oncocytaires.",
      "E": "L'évolution clinique se fait inéluctablement vers une hyperthyroïdie permanente."
    },
