      "B": "Cliniquement, elle se présente sous la forme d'un goitre de consistance \"pierreuse\", extrêmement dur, et indolore.",
      "C": "Elle peut s'intégrer dans le cadre d'une fibrose systémique multifocale.",
      "D": "Le traitement de première intention est toujours chirurgical radical.",
